(function(){'use strict';function syncSliderValue(slider){var targetId=slider.getAttribute('data-iq-value-target');if(!targetId)return;var target=document.getElementById(targetId);if(!target)return;target.textContent=slider.value;slider.setAttribute('aria-valuenow',slider.value);}function initSliders(){document.querySelectorAll('.iq-range[data-iq-value-target]').forEach(function(slider){syncSliderValue(slider);slider.addEventListener('input',function(){syncSliderValue(slider);});});}function setSplitVisible(isOn){var splitRow=document.getElementById('split-row-wrapper');var unitCost2=document.getElementById('iq-unit-cost-2');if(splitRow)splitRow.classList.toggle('is-visible',isOn);if(unitCost2)unitCost2.classList.toggle('is-visible',isOn);}function initSplitToggle(){var toggle=document.getElementById('iq-split-toggle');if(!toggle)return;setSplitVisible(toggle.checked);toggle.addEventListener('change',function(){setSplitVisible(toggle.checked);});}function initQualityToggle(){var track=document.querySelector('.iq-toggle-track');if(!track)return;track.addEventListener('click',function(event){var btn=event.target.closest('.iq-toggle-btn');if(!btn||!track.contains(btn))return;event.preventDefault();track.querySelectorAll('.iq-toggle-btn').forEach(function(el){el.classList.remove('is-active');});btn.classList.add('is-active');});}function init(){initSliders();initSplitToggle();initQualityToggle();}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();
